def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    # A scattered marker suppresses extension along its row and column.
    # Unmarked rows of the rectangle extend horizontally; unmarked columns
    # extend vertically through the full canvas. Preserve all marker cells.
    blocker = 1 if any(1 in row for row in grid) else 8
    marked_rows = {r for r in range(h) for c in range(w) if grid[r][c] == blocker}
    marked_cols = {c for r in range(h) for c in range(w) if grid[r][c] == blocker}
    for r in range(r0, r1 + 1):
        if r not in marked_rows:
            for c in range(w):
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        if c not in marked_cols:
            for r in range(h):
                out[r][c] = 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == blocker:
                out[r][c] = blocker
    return out

